        let diags = lint_nodes(&*engine(), src);
        assert!(has_id(&diags, "OR2"), "got: {diags:?}");
    }

    #[test]
    fn or2_not_fire_on_short_circuit() {
        let src = "if a || b\n    c = 1;\nend\n";
        let diags = lint_nodes(&*engine(), src);
        assert!(!has_id(&diags, "OR2"), "got: {diags:?}");
    }

    // -- MINV -----------------------------------------------------------------

    #[test]
    fn minv_fires_on_inv_times_vector() {
        let src = "x = inv(A) * b;\n";
        let diags = lint_nodes(&*engine(), src);
        assert!(has_id(&diags, "MINV"), "got: {diags:?}");
    }

