        let diags = lint_nodes(&*engine(), src);
        assert!(!has_id(&diags, "MINV"), "got: {diags:?}");
    }

    // -- GFLD / SFLD ----------------------------------------------------------

    #[test]
    fn gfld_fires_on_getfield() {
