ORIG = pathlib.Path("crates/mlt_rules/src/performance.rs").read_text()
PERF = pathlib.Path("crates/mlt_rules/src/performance")

def extract_method_orig(name):
    lines = ORIG.split("\n")
    for i, l in enumerate(lines):
        if re.match(rf"^    fn {re.escape(name)}\b", l):
            close = None
            for k in range(i+1, len(lines)):
                if lines[k] == "    }":
                    close = k
                    break
            return "\n".join(lines[i:close+1])

def extract_method_new(fname, name):
    lines = (PERF / fname).read_text().split("\n")
    for i, l in enumerate(lines):
        if re.match(rf"^    pub\(crate\) fn {re.escape(name)}\b", l):
            close = None
            for k in range(i+1, len(lines)):
                if lines[k] == "    }":
                    close = k
                    break
            return "\n".join(lines[i:close+1])

