                if flines[k] == "    }":
                    close = k
                    break
            assert close is not None, f"{path}: no close for {name}"
            doc = []
            j = i - 1
            while j >= 0 and flines[j].lstrip().startswith("///"):
                doc.append(flines[j])
                j -= 1
            doc.reverse()
            return "\n".join(doc + ["\n".join(flines[i:close + 1])])
    return None

