            replacement: replacement.into(),
            additional_edits: additional,
        }
    }

    /// Convenience: create an insertion (zero-width replacement) at `offset`.
    pub fn insert(offset: usize, text: impl Into<String>) -> Self {
        Self::new(offset..offset, text)
