//! Standalone compile harness for the split `performance/` module tree.
//!
//! Stubs `mlt_core`, `tree_sitter`, `serde` (derive), `inventory` and
//! `crate::test_util` with the exact API surface the performance module uses,
//! then includes the real `performance/` directory. Compile-only validation
//! (tests will fail at runtime because `parse` is a stub).
#![allow(dead_code)]
#![allow(unused_imports)]

use std::ops::Range;
use std::path::Path;

// ---------------------------------------------------------------------------
// Stub: tree_sitter
// ---------------------------------------------------------------------------
pub mod tree_sitter {
    use std::marker::PhantomData;

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    pub struct Point {
        pub row: usize,
        pub column: usize,
    }

    #[derive(Debug, Clone, Copy)]
    pub struct Node<'a> {
        pub(crate) kind_name: &'static str,
        pub(crate) start: usize,
        pub(crate) end: usize,
        pub(crate) _marker: PhantomData<&'a ()>,
    }

    impl<'a> Node<'a> {
        pub fn kind(&self) -> &str {
            self.kind_name
        }
        pub fn child_count(&self) -> usize {
            0
        }
        pub fn child(&self, _i: usize) -> Option<Node<'a>> {
            None
        }
        pub fn named_child_count(&self) -> usize {
            0
        }
        pub fn named_child(&self, _i: usize) -> Option<Node<'a>> {
            None
        }
        pub fn child_by_field_name(&self, _name: &str) -> Option<Node<'a>> {
            None
        }
        pub fn start_byte(&self) -> usize {
            self.start
        }
        pub fn end_byte(&self) -> usize {
            self.end
        }
        pub fn start_position(&self) -> Point {
            Point { row: 0, column: 0 }
        }
        pub fn end_position(&self) -> Point {
            Point { row: 0, column: 0 }
        }
        pub fn parent(&self) -> Option<Node<'a>> {
            None
        }
        pub fn id(&self) -> usize {
            self.start
        }
        pub fn walk(&self) -> TreeCursor<'a> {
            TreeCursor {
                _marker: PhantomData,
            }
        }
        pub fn children<'tree>(
            &self,
            _cursor: &mut TreeCursor<'tree>,
        ) -> impl Iterator<Item = Node<'tree>> + 'tree {
            std::iter::empty()
        }
    }

    pub struct TreeCursor<'a> {
        pub(crate) _marker: PhantomData<&'a ()>,
    }

    #[derive(Debug)]
    pub struct Tree {
        pub(crate) root: Node<'static>,
    }

    impl Tree {
        pub fn root_node(&self) -> Node<'_> {
            self.root
        }
    }
}

// ---------------------------------------------------------------------------
// Stub: mlt_core
// ---------------------------------------------------------------------------
pub mod mlt_core {
