}

impl RuleRegistration {
    pub const fn new(id: &'static str, factory: RuleFactory) -> Self {
        Self { id, factory }
    }
}

// ---------------------------------------------------------------------------
// Stub: test_util
// ---------------------------------------------------------------------------
#[cfg(test)]
pub mod test_util {
    use super::*;
    use mlt_core::{Diagnostic, FileContext, NodeContext, Rule};
    use std::path::Path;
    use tree_sitter::Node;

    pub fn parse(_source: &str) -> tree_sitter::Tree {
        tree_sitter::Tree {
            root: Node {
                kind_name: "source_file",
                start: 0,
                end: 0,
                _marker: std::marker::PhantomData,
            },
        }
    }

    pub fn lint_nodes(rule: &dyn Rule, source: &str) -> Vec<Diagnostic> {
        let tree = parse(source);
        let path = Path::new("test.m");
        let targets: Vec<&str> = rule.target_node_types().to_vec();
        let mut diagnostics = Vec::new();

        fn walk(
            node: Node,
            source: &str,
            path: &Path,
            targets: &[&str],
            rule: &dyn Rule,
            diagnostics: &mut Vec<Diagnostic>,
        ) {
            if targets.contains(&node.kind()) {
                let ctx = NodeContext {
                    node,
                    source,
                    file_path: path,
                };
                diagnostics.extend(rule.check(&ctx));
            }
            let mut cursor = node.walk();
            for child in node.children(&mut cursor) {
                walk(child, source, path, targets, rule, diagnostics);
            }
        }

        walk(tree.root_node(), source, path, &targets, rule, &mut diagnostics);
        diagnostics
    }

    pub fn lint_file(rule: &dyn Rule, source: &str) -> Vec<Diagnostic> {
        let tree = parse(source);
        let ctx = FileContext {
            tree: &tree,
            source,
            file_path: Path::new("test.m"),
        };
        rule.check_file(&ctx)
    }

    pub fn has_id(diags: &[Diagnostic], id: &str) -> bool {
        diags.iter().any(|d| d.rule_id == id)
    }
}

// ---------------------------------------------------------------------------
// The real (split) performance module
// ---------------------------------------------------------------------------
pub mod performance;

